function hasClosePair(nums: number[], indexGap: number, valueGap: number): boolean {
  const w = valueGap + 1;
  const buckets = new Map<number, number>();
  for (let i = 0; i < nums.length; i++) {
    const x = nums[i], b = Math.floor(x / w);
    if (buckets.has(b)) return true;
    const left = buckets.get(b - 1), right = buckets.get(b + 1);
    if (left !== undefined && x - left <= valueGap) return true;
    if (right !== undefined && right - x <= valueGap) return true;
    buckets.set(b, x);
    if (i >= indexGap) buckets.delete(Math.floor(nums[i - indexGap] / w));
  }
  return false;
}

